146	func ompPrivateDir() string {
147		return filepath.Join(protocol.DefaultSessionDir(protocol.RepoRoot()), "omp")
148	}
149	
150	func cachedSessionPath() string {
151		return filepath.Join(ompPrivateDir(), activeSessionFile)
152	}
153	
154	func cacheSessionID(id string) error {
155		if !validSessionID(id) {
156			return fmt.Errorf("unsafe session id %q", id)
157		}
158		if err := ensurePrivateDir(ompPrivateDir()); err != nil {
159			return err
160		}
161		return atomicWriteFile(cachedSessionPath(), []byte(id+"\n"), 0o600)
162	}
163	
164	func readCachedSessionID() string {
165		data, err := os.ReadFile(cachedSessionPath())
166		if err != nil {
167			return ""
168		}
169		id := strings.TrimSpace(string(data))
170		if !validSessionID(id) {
171			return ""
172		}
173		return id
174	}
175	
176	func clearCachedSessionID() error {
177		err := os.Remove(cachedSessionPath())
178		if err != nil && !os.IsNotExist(err) {
179			return fmt.Errorf("clear active session: %w", err)
180		}
181		return nil
182	}
183	
184	func ensurePrivateDir(path string) error {
185		if err := os.MkdirAll(path, 0o700); err != nil {
186			return fmt.Errorf("create omp private directory: %w", err)
187		}
188		info, err := os.Lstat(path)
189		if err != nil {
190			return fmt.Errorf("inspect omp private directory: %w", err)
191		}
192		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
193			return fmt.Errorf("omp private path is not a directory: %s", path)
194		}
195		//nolint:gosec // Directories require execute bits; 0700 is the private-directory equivalent of 0600.
196		if err := os.Chmod(path, 0o700); err != nil {
197			return fmt.Errorf("secure omp private directory: %w", err)
198		}
199		return nil
200	}
201	
202	func snapshotSession(source, cwd, sessionID string) (string, error) {
203		if !validSessionID(sessionID) {
204			return "", fmt.Errorf("unsafe session id %q", sessionID)
205		}
206		if strings.TrimSpace(source) == "" {
207			return "", errors.New("session file is required for agent_end")
208		}
209		if strings.TrimSpace(cwd) == "" {
210			return "", errors.New("cwd is required for agent_end snapshot")
211		}
212		sessionDir, err := New().GetSessionDir(cwd)
213		if err != nil {
214			return "", err
215		}
216		canonicalSessionDir, err := canonicalPath(sessionDir)
217		if err != nil {
218			return "", fmt.Errorf("resolve omp session directory: %w", err)
219		}
220		canonicalSource, err := canonicalPath(source)
221		if err != nil {
222			return "", fmt.Errorf("resolve omp session file: %w", err)
223		}
224		if filepath.Dir(canonicalSource) != canonicalSessionDir || filepath.Ext(canonicalSource) != ".jsonl" {
225			return "", errors.New("omp session file is outside the managed session directory")
226		}
227		info, err := os.Stat(canonicalSource)
228		if err != nil {
229			return "", fmt.Errorf("inspect omp session: %w", err)
230		}
231		if !info.Mode().IsRegular() {
232			return "", errors.New("omp session file is not a regular file")
233		}
234		src, err := os.Open(canonicalSource)
235		if err != nil {
236			return "", fmt.Errorf("open omp session: %w", err)
237		}
238		defer src.Close()
239	
240		snapshotDir := filepath.Join(canonicalSessionDir, ".entire")
241		if err := ensurePrivateDir(snapshotDir); err != nil {
242			return "", err
243		}
244		destination := filepath.Join(snapshotDir, sessionID+".jsonl")
245		tmp, err := os.CreateTemp(snapshotDir, ".snapshot-*")
246		if err != nil {
247			return "", fmt.Errorf("create transcript snapshot: %w", err)
248		}
249		tmpName := tmp.Name()
250		defer os.Remove(tmpName)
251	
252		if err := tmp.Chmod(0o600); err != nil {
253			return "", errors.Join(err, tmp.Close())
254		}
255		if _, err := io.Copy(tmp, src); err != nil {
256			return "", errors.Join(fmt.Errorf("copy transcript snapshot: %w", err), tmp.Close())
257		}
258		if err := tmp.Sync(); err != nil {
259			return "", errors.Join(fmt.Errorf("sync transcript snapshot: %w", err), tmp.Close())
260		}
261		if err := tmp.Close(); err != nil {
262			return "", fmt.Errorf("close transcript snapshot: %w", err)
263		}
264		if err := os.Rename(tmpName, destination); err != nil {
265			return "", fmt.Errorf("publish transcript snapshot: %w", err)
266		}
267		return destination, nil
268	}
269	
270	func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
271		tmp, err := os.CreateTemp(filepath.Dir(path), ".write-*")
272		if err != nil {
273			return err
274		}
275		tmpName := tmp.Name()
276		defer os.Remove(tmpName)
277		if err := tmp.Chmod(mode); err != nil {
278			return errors.Join(err, tmp.Close())
279		}
280		if _, err := tmp.Write(data); err != nil {
281			return errors.Join(err, tmp.Close())
282		}
283		if err := tmp.Close(); err != nil {
284			return err
285		}
286		return os.Rename(tmpName, path)
287	}
288	
289	func isOwnedExtension(data []byte) bool {
290		return bytes.Contains(data, []byte(extensionMarker)) ||
291			bytes.Contains(data, []byte(legacyExtensionMarker))
292	}
293	
294	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
295		root := protocol.RepoRoot()
296		path := filepath.Join(root, extensionRelFile)
297		if data, err := os.ReadFile(path); err == nil {
298			if bytes.Equal(data, []byte(generatedExtension)) && !force {
299				return 0, nil
300			}
301			if !isOwnedExtension(data) && !force {
302				return 0, fmt.Errorf("refusing to overwrite foreign omp extension %s", path)
303			}
304		} else if !os.IsNotExist(err) {
305			return 0, err
306		}
307	
308		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
309			return 0, fmt.Errorf("create omp extension directory: %w", err)
310		}
311		if err := atomicWriteFile(path, []byte(generatedExtension), 0o600); err != nil {
312			return 0, fmt.Errorf("write omp extension: %w", err)
313		}
314		return 4, nil
315	}
316	
317	func (a *Agent) UninstallHooks() error {
318		root := protocol.RepoRoot()
319		path := filepath.Join(root, extensionRelFile)
320		data, err := os.ReadFile(path)
321		if os.IsNotExist(err) {
322			return nil
323		}
324		if err != nil {
325			return fmt.Errorf("read omp extension: %w", err)
326		}
327		if !isOwnedExtension(data) {
328			return nil
329		}
330		if err := os.Remove(path); err != nil {
331			return fmt.Errorf("remove omp extension: %w", err)
332		}
333		_ = os.Remove(filepath.Join(root, extensionRelDir))
334		return nil
335	}
336	
337	func (a *Agent) AreHooksInstalled() bool {
338		data, err := os.ReadFile(filepath.Join(protocol.RepoRoot(), extensionRelFile))
339		return err == nil && isOwnedExtension(data)
340	}
