1	package omp
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"strings"
12		"time"
13		"unicode"
14	
15		"github.com/entireio/external-agents/agents/entire-agent-omp/internal/protocol"
16	)
17	
18	const maxSessionLine = 10 * 1024 * 1024
19	
20	type sessionEntry struct {
21		Type      string          `json:"type"`
22		ID        string          `json:"id"`
23		ParentID  *string         `json:"parentId"`
24		Timestamp string          `json:"timestamp"`
25		Model     string          `json:"model"`
26		Message   *sessionMessage `json:"message"`
27	}
28	
29	type sessionMessage struct {
30		Role       string          `json:"role"`
31		Content    json.RawMessage `json:"content"`
32		Model      string          `json:"model"`
33		Usage      *sessionUsage   `json:"usage"`
34		ToolCallID string          `json:"toolCallId"`
35		ToolName   string          `json:"toolName"`
36		IsError    bool            `json:"isError"`
37	}
38	
39	type sessionUsage struct {
40		Input  int `json:"input"`
41		Output int `json:"output"`
42	}
43	
44	type contentBlock struct {
45		Type      string          `json:"type"`
46		Text      string          `json:"text"`
47		ID        string          `json:"id"`
48		Name      string          `json:"name"`
49		Arguments json.RawMessage `json:"arguments"`
50	}
51	
52	type parsedEntry struct {
53		Line  int
54		Entry sessionEntry
55	}
56	
57	type parsedSession struct {
58		Header  sessionHeader
59		Entries []parsedEntry
60		Active  []parsedEntry
61		Lines   int
62	}
63	
64	func parseSession(data []byte) (*parsedSession, error) {
65		header, err := parseSessionHeader(data)
66		if err != nil {
67			return nil, err
68		}
69		return parseSessionEntries(data, header)
70	}
71	
72	func parseSessionEntries(data []byte, header sessionHeader) (*parsedSession, error) {
73		scanner := bufio.NewScanner(bytes.NewReader(data))
74		scanner.Buffer(make([]byte, 64*1024), maxSessionLine+1)
75		result := &parsedSession{Header: header}
76		byID := make(map[string]parsedEntry)
77		var last *parsedEntry
78		for scanner.Scan() {
79			result.Lines++
80			if len(scanner.Bytes()) > maxSessionLine {
81				return nil, fmt.Errorf("scan session: line %d exceeds %d bytes", result.Lines, maxSessionLine)
82			}
83			var kind struct {
84				Type string `json:"type"`
85			}
86			if json.Unmarshal(scanner.Bytes(), &kind) != nil {
87				continue
88			}
89			if kind.Type == "title" || kind.Type == "session" {
90				continue
91			}
92			var entry sessionEntry
93			if json.Unmarshal(scanner.Bytes(), &entry) != nil || entry.ID == "" || entry.Type == "" {
94				continue
95			}
96			record := parsedEntry{Line: result.Lines, Entry: entry}
97			result.Entries = append(result.Entries, record)
98			byID[entry.ID] = record
99			recordCopy := record
100			last = &recordCopy
101		}
102		if err := scanner.Err(); err != nil {
103			return nil, fmt.Errorf("scan session: %w", err)
104		}
105	
106		seen := make(map[string]bool)
107		for last != nil && !seen[last.Entry.ID] {
108			seen[last.Entry.ID] = true
109			result.Active = append(result.Active, *last)
110			if last.Entry.ParentID == nil || *last.Entry.ParentID == "" {
111				break
112			}
113			parent, ok := byID[*last.Entry.ParentID]
114			if !ok {
115				break
116			}
117			parentCopy := parent
118			last = &parentCopy
119		}
120		for left, right := 0, len(result.Active)-1; left < right; left, right = left+1, right-1 {
121			result.Active[left], result.Active[right] = result.Active[right], result.Active[left]
122		}
123		return result, nil
124	}
125	
126	func parseSessionLoose(data []byte) (*parsedSession, error) {
127		header, _ := parseSessionHeader(data)
128		return parseSessionEntries(data, header)
129	}
130	
131	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
132		if input == nil || strings.TrimSpace(input.SessionRef) == "" {
133			return protocol.AgentSessionJSON{}, errors.New("session_ref is required")
134		}
135		data, err := os.ReadFile(input.SessionRef)
136		if err != nil {
137			return protocol.AgentSessionJSON{}, err
138		}
139		header, headerErr := parseSessionHeader(data)
140		if headerErr == nil {
141			session, err := parseSessionEntries(data, header)
142			if err != nil {
143				return protocol.AgentSessionJSON{}, err
144			}
145			return protocol.AgentSessionJSON{
146				SessionID:     session.Header.ID,
147				AgentName:     "omp",
148				RepoPath:      session.Header.Cwd,
149				SessionRef:    input.SessionRef,
150				StartTime:     session.Header.Timestamp,
151				NativeData:    data,
152				ModifiedFiles: modifiedFiles(session.Active, 0),
153				NewFiles:      []string{},
154				DeletedFiles:  []string{},
155			}, nil
156		}
157		return protocol.AgentSessionJSON{
158			SessionID:     input.SessionID,
159			AgentName:     "omp",
160			RepoPath:      protocol.RepoRoot(),
161			SessionRef:    input.SessionRef,
162			StartTime:     time.Now().UTC().Format(time.RFC3339),
163			NativeData:    data,
164			ModifiedFiles: []string{},
165			NewFiles:      []string{},
166			DeletedFiles:  []string{},
167		}, nil
168	}
169	
170	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
171		if strings.TrimSpace(session.SessionRef) == "" {
172			return errors.New("session_ref is required")
173		}
174		dir := filepath.Dir(session.SessionRef)
